+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * How the customer list is narrowed down: a name search and a set of accepted
+ * statuses. Both halves are optional, and an empty filter matches everything.
+ *
+ * <p>This is part of the query the backend runs, not a sieve laid over an
+ * already fetched page: {@link CustomerRepository} applies it before it pages
+ * and before it counts.
+ *
+ * @param name     free text; whitespace-separated terms that must <em>all</em>
+ *                 occur in the first or the last name, ignoring case and accents
+ * @param statuses the statuses to show; empty means every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        // An EnumSet keeps the statuses in declaration order, which is the order
+        // the URL is written in.
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** {@code true} when this filter accepts every customer. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The name search, split into the terms a customer has to match all of. */
+    public List<String> terms() {
+        return name.isEmpty()
+                ? List.of()
+                : WHITESPACE.splitAsStream(name).map(CustomerFilter::fold).toList();
+    }
+
+    /** The test the backend applies to every customer. */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = terms();
+        return customer -> matchesStatus(customer) && matchesName(terms, customer);
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private static boolean matchesName(List<String> terms, Customer customer) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms.stream()
+                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /**
+     * Folds a string down to what matching actually compares: lower case and
+     * without accents, so that {@code makinen}, {@code MAKINEN} and
+     * {@code mäkinen} all reduce to the same thing.
+     */
+    private static String fold(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
