+ *
+ * <p>Named {@code …IT} so that {@code mvn test} stays a pure JVM run. Run it
+ * with {@code mvn -o test -Dtest=CustomerListViewBrowserIT}.
+ */
+@SpringBootTest(classes = Application.class,
+        webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void typingNarrowsTheListAndShowsUpInTheAddressBar() {
+        nameFilter().assertPlaceholder("Filter by name");
+        assertSummary("Showing 500 of 500");
+
+        nameFilter().setValue("virtanen");
+
+        assertSummary(Pattern.compile("Showing \\d+ of 500"));
+        assertThat(page).hasURL(Pattern.compile(".*/\\?name=virtanen$"));
+        assertTrue(summaryCount() > 0 && summaryCount() < 500,
+                "Virtanen must narrow the list: " + summaryText());
+        new GridElement(page.locator("vaadin-grid")).assertRowCount(summaryCount());
+    }
+
+    @Test
+    void statusesAreWrittenInDeclarationOrder() {
+        // Picked in the other order on purpose.
+        statusFilter().selectItems("CLOSED", "ACTIVE");
+
+        assertThat(page).hasURL(Pattern.compile(".*/\\?status=ACTIVE,CLOSED$"));
+    }
+
+    @Test
+    void bothFiltersEndUpInTheUrl() {
+        nameFilter().setValue("vir");
+        statusFilter().selectItems("ACTIVE", "CLOSED");
+
+        assertThat(page).hasURL(Pattern.compile(".*/\\?name=vir&status=ACTIVE,CLOSED$"));
+    }
+
+    @Test
+    void clearingTheFilterLeavesNoParametersBehind() {
+        nameFilter().setValue("vir");
+        statusFilter().selectItems("ACTIVE");
+        assertThat(page).hasURL(Pattern.compile(".*\\?name=vir.*"));
+
+        statusFilter().deselectItems("ACTIVE");
+        nameFilter().setValue("");
+
+        assertSummary("Showing 500 of 500");
+        assertThat(page).hasURL(Pattern.compile(".*/$"));
+    }
+
+    @Test
+    void aLinkWithAFilterOpensThatFilter() {
+        page.navigate(getUrl() + "/?name=aal&status=ACTIVE,CLOSED");
+        waitForVaadin();
+
+        nameFilter().assertValue("aal");
+        statusFilter().assertSelectedItems("ACTIVE", "CLOSED");
+        assertSummary(Pattern.compile("Showing \\d+ of 500"));
+        assertTrue(summaryCount() > 0 && summaryCount() < 500, summaryText());
+        new GridElement(page.locator("vaadin-grid")).assertRowCount(summaryCount());
+    }
+
+    @Test
+    void filteringDoesNotPushHistoryEntries() {
+        int entriesBefore = historyLength();
+        nameFilter().setValue("virtanen");
+        assertThat(page).hasURL(Pattern.compile(".*name=virtanen.*"));
+
+        assertEquals(entriesBefore, historyLength(),
+                "Filtering must replace the history entry, not add to it");
+    }
+
+    /** Typing a nine-letter name is one or two queries, not nine. */
+    @Test
+    void aBurstOfTypingIsOneQuery() {
+        // Let the initial load finish before the counting starts.
+        assertSummary("Showing 500 of 500");
+        new GridElement(page.locator("vaadin-grid")).assertRowCount(500);
+        page.waitForTimeout(500);
+        queryLog.clear();
+
+        Locator input = nameFilter().getInputLocator();
+        input.click();
+        input.pressSequentially("Lindqvist", new Locator.PressSequentiallyOptions().setDelay(60));
+
+        assertSummary(Pattern.compile("Showing [1-9]\\d* of 500"));
+        page.waitForTimeout(1000); // let any straggling query arrive
+
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing nine letters ran " + queryLog.pageQueries().size() + " page queries: "
+                        + queryLog.pageQueries());
+        assertTrue(queryLog.countQueries().size() <= 4,
+                "Typing nine letters ran " + queryLog.countQueries().size() + " count queries: "
+                        + queryLog.countQueries());
+        assertTrue(queryLog.rowsFetched() <= CustomerRepository.MAX_PAGE_SIZE,
+                "Typing pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    // --- helpers -----------------------------------------------------------
+
+    private TextFieldElement nameFilter() {
+        return new TextFieldElement(page.locator("vaadin-text-field"));
+    }
+
+    private MultiSelectComboBoxElement statusFilter() {
+        return MultiSelectComboBoxElement.getByLabel(page, "Status");
+    }
+
+    private Locator summary() {
+        return page.getByText(Pattern.compile("^Showing \\d+ of \\d+$"));
+    }
+
+    private String summaryText() {
+        return summary().textContent();
+    }
+
+    private int summaryCount() {
+        return Integer.parseInt(summaryText().split(" ")[1]);
+    }
+
+    private void assertSummary(String expected) {
+        assertThat(summary()).hasText(expected);
+    }
+
+    private void assertSummary(Pattern expected) {
+        assertThat(summary()).hasText(expected);
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("() => window.history.length")).intValue();
+    }
+
+    private void waitForVaadin() {
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+    }
+}
